import{_ as l,a0 as d,w as o,s as c,ao as p,I as t,x as s,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"Java 中的数据流和函数式编程 | LCTT x X-CMD","titleTemplate":false,"description":"Java 中的数据流和函数式编程 | LCTT (202002) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Java 中的数据流和函数式编程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Java 中的数据流和函数式编程 | LCTT (202002) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202002/20200102 Data streaming and functional programming in Java","title":"Java 中的数据流和函数式编程","tag":"202002","desc":""},"relativePath":"202002/20200102 Data streaming and functional programming in Java.md","filePath":"[post].md"}'),r={name:"202002/20200102 Data streaming and functional programming in Java.md"};function g(u,a,h,b,k,m){const e=d("Link");return o(),c("div",null,[a[18]||(a[18]=p(`<h1 id="java-中的数据流和函数式编程" tabindex="-1">Java 中的数据流和函数式编程 <a class="header-anchor" href="#java-中的数据流和函数式编程" aria-label="Permalink to “Java 中的数据流和函数式编程”">​</a></h1><blockquote><p>学习如何使用 Java 8 中的流 API 和函数式编程结构。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202002/06/002505flazlb4cg4aavvb4.jpg" alt=""></p><p>当 Java SE 8（又名核心 Java 8）在 2014 年被推出时，它引入了一些更改，从根本上影响了用它进行的编程。这些更改中有两个紧密相连的部分：流 API 和函数式编程构造。本文使用代码示例，从基础到高级特性，介绍每个部分并说明它们之间的相互作用。</p><h3 id="基础特性" tabindex="-1">基础特性 <a class="header-anchor" href="#基础特性" aria-label="Permalink to “基础特性”">​</a></h3><p>流 API 是在数据序列中迭代元素的简洁而高级的方法。包 <code>java.util.stream</code> 和 <code>java.util.function</code> 包含了用于流 API 和相关函数式编程构造的新库。当然，代码示例胜过千言万语。</p><p>下面的代码段用大约 2,000 个随机整数值填充了一个 <code>List</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Random rand = new Random2();</span></span>
<span class="line"><span>List&lt;Integer&gt; list = new ArrayList&lt;Integer&gt;();           // 空 list</span></span>
<span class="line"><span>for (int i = 0; i &lt; 2048; i++) list.add(rand.nextInt()); // 填充它</span></span></code></pre></div><p>另外用一个 <code>for</code> 循环可用于遍历填充列表，以将偶数值收集到另一个列表中。</p><p>流 API 提供了一种更简洁的方法来执行此操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>List &lt;Integer&gt; evens = list</span></span>
<span class="line"><span>    .stream()                      // 流化 list</span></span>
<span class="line"><span>    .filter(n -&gt; (n &amp; 0x1) == 0)   // 过滤出奇数值</span></span>
<span class="line"><span>    .collect(Collectors.toList()); // 收集偶数值</span></span></code></pre></div><p>这个例子有三个来自流 API 的函数：</p><ul><li><code>stream</code> 函数可以将<strong>集合</strong>转换为流，而流是一个每次可访问一个值的传送带。流化是惰性的（因此也是高效的），因为值是根据需要产生的，而不是一次性产生的。</li><li><code>filter</code> 函数确定哪些流的值（如果有的话）通过了处理管道中的下一个阶段，即 <code>collect</code> 阶段。<code>filter</code> 函数是 <ruby>高阶的<rt>higher-order</rt></ruby>，因为它的参数是一个函数 —— 在这个例子中是一个 lambda 表达式，它是一个未命名的函数，并且是 Java 新的函数式编程结构的核心。</li></ul><p>lambda 语法与传统的 Java 完全不同：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>n -&gt; (n &amp; 0x1) == 0</span></span></code></pre></div><p>箭头（一个减号后面紧跟着一个大于号）将左边的参数列表与右边的函数体分隔开。参数 <code>n</code> 虽未明确类型，但也可以明确。在任何情况下，编译器都会发现 <code>n</code> 是个 <code>Integer</code>。如果有多个参数，这些参数将被括在括号中，并用逗号分隔。</p><p>在本例中，函数体检查一个整数的最低位（最右）是否为零，这用来表示偶数。过滤器应返回一个布尔值。尽管可以，但该函数的主体中没有显式的 <code>return</code>。如果主体没有显式的 <code>return</code>，则主体的最后一个表达式即是返回值。在这个例子中，主体按照 lambda 编程的思想编写，由一个简单的布尔表达式 <code>(n &amp; 0x1) == 0</code> 组成。</p><ul><li><code>collect</code> 函数将偶数值收集到引用为 <code>evens</code> 的列表中。如下例所示，<code>collect</code> 函数是线程安全的，因此，即使在多个线程之间共享了过滤操作，该函数也可以正常工作。</li></ul><h3 id="方便的功能和轻松实现多线程" tabindex="-1">方便的功能和轻松实现多线程 <a class="header-anchor" href="#方便的功能和轻松实现多线程" aria-label="Permalink to “方便的功能和轻松实现多线程”">​</a></h3><p>在生产环境中，数据流的源可能是文件或网络连接。为了学习流 API, Java 提供了诸如 <code>IntStream</code> 这样的类型，它可以用各种类型的元素生成流。这里有一个 <code>IntStream</code> 的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>IntStream                          // 整型流</span></span>
<span class="line"><span>    .range(1, 2048)                // 生成此范围内的整型流</span></span>
<span class="line"><span>    .parallel()                    // 为多个线程分区数据</span></span>
<span class="line"><span>    .filter(i -&gt; ((i &amp; 0x1) &gt; 0))  // 奇偶校验 - 只允许奇数通过</span></span>
<span class="line"><span>    .forEach(System.out::println); // 打印每个值</span></span></code></pre></div><p><code>IntStream</code> 类型包括一个 <code>range</code> 函数，该函数在指定的范围内生成一个整数值流，在本例中，以 1 为增量，从 1 递增到 2048。<code>parallel</code> 函数自动划分该工作到多个线程中，在各个线程中进行过滤和打印。（线程数通常与主机系统上的 CPU 数量匹配。）函数 <code>forEach</code> 参数是一个<em>方法引用</em>，在本例中是对封装在 <code>System.out</code> 中的 <code>println</code> 方法的引用，方法输出类型为 <code>PrintStream</code>。方法和构造器引用的语法将在稍后讨论。</p><p>由于具有多线程，因此整数值整体上以任意顺序打印，但在给定线程中是按顺序打印的。例如，如果线程 T1 打印 409 和 411，那么 T1 将按照顺序 409-411 打印，但是其它某个线程可能会预先打印 2045。<code>parallel</code> 调用后面的线程是并发执行的，因此它们的输出顺序是不确定的。</p><h3 id="map-reduce-模式" tabindex="-1">map/reduce 模式 <a class="header-anchor" href="#map-reduce-模式" aria-label="Permalink to “map/reduce 模式”">​</a></h3><p><em>map/reduce</em> 模式在处理大型数据集方面变得很流行。一个 map/reduce 宏操作由两个微操作构成。首先，将数据分散（<ruby>映射<rt>mapped</rt></ruby>）到各个工作程序中，然后将单独的结果收集在一起 —— 也可能收集统计起来成为一个值，即<ruby>归约<rt>reduction</rt></ruby>。归约可以采用不同的形式，如以下示例所示。</p><p>下面 <code>Number</code> 类的实例用 <code>EVEN</code> 或 <code>ODD</code> 表示有奇偶校验的整数值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>public class Number {</span></span>
<span class="line"><span>    enum Parity { EVEN, ODD }</span></span>
<span class="line"><span>    private int value;</span></span>
<span class="line"><span>    public Number(int n) { setValue(n); }</span></span>
<span class="line"><span>    public void setValue(int value) { this.value = value; }</span></span>
<span class="line"><span>    public int getValue() { return this.value; }</span></span>
<span class="line"><span>    public Parity getParity() {</span></span>
<span class="line"><span>        return ((value &amp; 0x1) == 0) ? Parity.EVEN : Parity.ODD;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    public void dump() {</span></span>
<span class="line"><span>        System.out.format(&quot;Value: %2d (parity: %s)\\n&quot;, getValue(),</span></span>
<span class="line"><span>                          (getParity() == Parity.ODD ? &quot;odd&quot; : &quot;even&quot;));</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>下面的代码演示了用 <code>Number</code> 流进行 map/reduce 的情形，从而表明流 API 不仅可以处理 <code>int</code> 和 <code>float</code> 等基本类型，还可以处理程序员自定义的类类型。</p><p>在下面的代码段中，使用了 <code>parallelStream</code> 而不是 <code>stream</code> 函数对随机整数值列表进行流化处理。与前面介绍的 <code>parallel</code> 函数一样，<code>parallelStream</code> 变体也可以自动执行多线程。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>final int howMany = 200;</span></span>
<span class="line"><span>Random r = new Random();</span></span>
<span class="line"><span>Number[] nums = new Number[howMany];</span></span>
<span class="line"><span>for (int i = 0; i &lt; howMany; i++) nums[i] = new Number(r.nextInt(100));</span></span>
<span class="line"><span>List&lt;Number&gt; listOfNums = Arrays.asList(nums);  // 将数组转化为 list</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Integer sum4All = listOfNums</span></span>
<span class="line"><span>    .parallelStream()           // 自动执行多线程</span></span>
<span class="line"><span>    .mapToInt(Number::getValue) // 使用方法引用，而不是 lambda</span></span>
<span class="line"><span>    .sum();                     // 将流值计算出和值</span></span>
<span class="line"><span>System.out.println(&quot;The sum of the randomly generated values is: &quot; + sum4All);</span></span></code></pre></div><p>高阶的 <code>mapToInt</code> 函数可以接受一个 lambda 作为参数，但在本例中，它接受一个方法引用，即 <code>Number::getValue</code>。<code>getValue</code> 方法不需要参数，它返回给定的 <code>Number</code> 实例的 <code>int</code> 值。语法并不复杂：类名 <code>Number</code> 后跟一个双冒号和方法名。回想一下先前的例子 <code>System.out::println</code>，它在 <code>System</code> 类中的 <code>static</code> 属性 <code>out</code> 后面有一个双冒号。</p><p>方法引用 <code>Number::getValue</code> 可以用下面的 lambda 表达式替换。参数 <code>n</code> 是流中的 <code>Number</code> 实例中的之一：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mapToInt(n -&gt; n.getValue())</span></span></code></pre></div><p>通常，lambda 表达式和方法引用是可互换的：如果像 <code>mapToInt</code> 这样的高阶函数可以采用一种形式作为参数，那么这个函数也可以采用另一种形式。这两个函数式编程结构具有相同的目的 —— 对作为参数传入的数据执行一些自定义操作。在两者之间进行选择通常是为了方便。例如，lambda 可以在没有封装类的情况下编写，而方法则不能。我的习惯是使用 lambda，除非已经有了适当的封装方法。</p><p>当前示例末尾的 <code>sum</code> 函数通过结合来自 <code>parallelStream</code> 线程的部分和，以线程安全的方式进行归约。但是，程序员有责任确保在 <code>parallelStream</code> 调用引发的多线程过程中，程序员自己的函数调用（在本例中为 <code>getValue</code>）是线程安全的。</p><p>最后一点值得强调。lambda 语法鼓励编写<ruby>纯函数<rt>pure function</rt></ruby>，即函数的返回值仅取决于传入的参数（如果有）；纯函数没有副作用，例如更新一个类中的 <code>static</code> 字段。因此，纯函数是线程安全的，并且如果传递给高阶函数的函数参数（例如 <code>filter</code> 和 <code>map</code> ）是纯函数，则流 API 效果最佳。</p><p>对于更细粒度的控制，有另一个流 API 函数，名为 <code>reduce</code>，可用于对 <code>Number</code> 流中的值求和:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Integer sum4AllHarder = listOfNums</span></span>
<span class="line"><span>    .parallelStream()                           // 多线程</span></span>
<span class="line"><span>    .map(Number::getValue)                      // 每个 Number 的值</span></span>
<span class="line"><span>    .reduce(0, (sofar, next) -&gt; sofar + next);  // 求和</span></span></code></pre></div><p>此版本的 <code>reduce</code> 函数带有两个参数，第二个参数是一个函数：</p><ul><li>第一个参数（在这种情况下为零）是<em>特征</em>值，该值用作求和操作的初始值，并且在求和过程中流结束时用作默认值。</li><li>第二个参数是<em>累加器</em>，在本例中，这个 lambda 表达式有两个参数：第一个参数（<code>sofar</code>）是正在运行的和，第二个参数（<code>next</code>）是来自流的下一个值。运行的和以及下一个值相加，然后更新累加器。请记住，由于开始时调用了 <code>parallelStream</code>，因此 <code>map</code> 和 <code>reduce</code> 函数现在都在多线程上下文中执行。</li></ul><p>在到目前为止的示例中，流值被收集，然后被规约，但是，通常情况下，流 API 中的 <code>Collectors</code> 可以累积值，而不需要将它们规约到单个值。正如下一个代码段所示，收集活动可以生成任意丰富的数据结构。该示例使用与前面示例相同的 <code>listOfNums</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Map&lt;Number.Parity, List&lt;Number&gt;&gt; numMap = listOfNums</span></span>
<span class="line"><span>    .parallelStream()</span></span>
<span class="line"><span>    .collect(Collectors.groupingBy(Number::getParity));</span></span>
<span class="line"><span></span></span>
<span class="line"><span>List&lt;Number&gt; evens = numMap.get(Number.Parity.EVEN);</span></span>
<span class="line"><span>List&lt;Number&gt; odds = numMap.get(Number.Parity.ODD);</span></span></code></pre></div><p>第一行中的 <code>numMap</code> 指的是一个 <code>Map</code>，它的键是一个 <code>Number</code> 奇偶校验位（<code>ODD</code> 或 <code>EVEN</code>），其值是一个具有指定奇偶校验位值的 <code>Number</code> 实例的 <code>List</code>。同样，通过 <code>parallelStream</code> 调用进行多线程处理，然后 <code>collect</code> 调用（以线程安全的方式）将部分结果组装到 <code>numMap</code> 引用的 <code>Map</code> 中。然后，在 <code>numMap</code> 上调用 <code>get</code> 方法两次，一次获取 <code>evens</code>，第二次获取 <code>odds</code>。</p><p>实用函数 <code>dumpList</code> 再次使用来自流 API 的高阶 <code>forEach</code> 函数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>private void dumpList(String msg, List&lt;Number&gt; list) {</span></span>
<span class="line"><span>    System.out.println(&quot;\\n&quot; + msg);</span></span>
<span class="line"><span>    list.stream().forEach(n -&gt; n.dump()); // 或者使用 forEach(Number::dump)</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这是示例运行中程序输出的一部分：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>The sum of the randomly generated values is: 3322</span></span>
<span class="line"><span>The sum again, using a different method:     3322</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Evens:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Value: 72 (parity: even)</span></span>
<span class="line"><span>Value: 54 (parity: even)</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>Value: 92 (parity: even)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Odds:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Value: 35 (parity: odd)</span></span>
<span class="line"><span>Value: 37 (parity: odd)</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>Value: 41 (parity: odd)</span></span></code></pre></div><h3 id="用于代码简化的函数式结构" tabindex="-1">用于代码简化的函数式结构 <a class="header-anchor" href="#用于代码简化的函数式结构" aria-label="Permalink to “用于代码简化的函数式结构”">​</a></h3><p>函数式结构（如方法引用和 lambda 表达式）非常适合在流 API 中使用。这些构造代表了 Java 中对高阶函数的主要简化。即使在糟糕的过去，Java 也通过 <code>Method</code> 和 <code>Constructor</code> 类型在技术上支持高阶函数，这些类型的实例可以作为参数传递给其它函数。由于其复杂性，这些类型在生产级 Java 中很少使用。例如，调用 <code>Method</code> 需要对象引用（如果方法是非<strong>静态</strong>的）或至少一个类标识符（如果方法是<strong>静态</strong>的）。然后，被调用的 <code>Method</code> 的参数作为<strong>对象</strong>实例传递给它，如果没有发生多态（那会出现另一种复杂性！），则可能需要显式向下转换。相比之下，lambda 和方法引用很容易作为参数传递给其它函数。</p><p>但是，新的函数式结构在流 API 之外具有其它用途。考虑一个 Java GUI 程序，该程序带有一个供用户按下的按钮，例如，按下以获取当前时间。按钮按下的事件处理程序可能编写如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>JButton updateCurrentTime = new JButton(&quot;Update current time&quot;);</span></span>
<span class="line"><span>updateCurrentTime.addActionListener(new ActionListener() {</span></span>
<span class="line"><span>    @Override</span></span>
<span class="line"><span>    public void actionPerformed(ActionEvent e) {</span></span>
<span class="line"><span>        currentTime.setText(new Date().toString());</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>});</span></span></code></pre></div><p>这个简短的代码段很难解释。关注第二行，其中方法 <code>addActionListener</code> 的参数开始如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>new ActionListener() {</span></span></code></pre></div><p>这似乎是错误的，因为 <code>ActionListener</code> 是一个<strong>抽象</strong>接口，而<strong>抽象</strong>类型不能通过调用 <code>new</code> 实例化。但是，事实证明，还有其它一些实例被实例化了：一个实现此接口的未命名内部类。如果上面的代码封装在名为 <code>OldJava</code> 的类中，则该未命名的内部类将被编译为 <code>OldJava$1.class</code>。<code>actionPerformed</code> 方法在这个未命名的内部类中被重写。</p><p>现在考虑使用新的函数式结构进行这个令人耳目一新的更改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>updateCurrentTime.addActionListener(e -&gt; currentTime.setText(new Date().toString()));</span></span></code></pre></div><p>lambda 表达式中的参数 <code>e</code> 是一个 <code>ActionEvent</code> 实例，而 lambda 的主体是对按钮上的 <code>setText</code> 的简单调用。</p><h3 id="函数式接口和函数组合" tabindex="-1">函数式接口和函数组合 <a class="header-anchor" href="#函数式接口和函数组合" aria-label="Permalink to “函数式接口和函数组合”">​</a></h3><p>到目前为止，使用的 lambda 已经写好了。但是，为了方便起见，我们可以像引用封装方法一样引用 lambda 表达式。以下一系列简短示例说明了这一点。</p><p>考虑以下接口定义：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@FunctionalInterface // 可选，通常省略</span></span>
<span class="line"><span>interface BinaryIntOp {</span></span>
<span class="line"><span>    abstract int compute(int arg1, int arg2); // abstract 声明可以被删除</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>注释 <code>@FunctionalInterface</code> 适用于声明<em>唯一</em>抽象方法的任何接口；在本例中，这个抽象接口是 <code>compute</code>。一些标准接口，（例如具有唯一声明方法 <code>run</code> 的 <code>Runnable</code> 接口）同样符合这个要求。在此示例中，<code>compute</code> 是已声明的方法。该接口可用作引用声明中的目标类型：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>BinaryIntOp div = (arg1, arg2) -&gt; arg1 / arg2;</span></span>
<span class="line"><span>div.compute(12, 3); // 4</span></span></code></pre></div><p>包 <code>java.util.function</code> 提供各种函数式接口。以下是一些示例。</p><p>下面的代码段介绍了参数化的 <code>Predicate</code> 函数式接口。在此示例中，带有参数 <code>String</code> 的 <code>Predicate&lt;String&gt;</code> 类型可以引用具有 <code>String</code> 参数的 lambda 表达式或诸如 <code>isEmpty</code> 之类的 <code>String</code> 方法。通常情况下，Predicate 是一个返回布尔值的函数。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Predicate&lt;String&gt; pred = String::isEmpty; // String 方法的 predicate 声明</span></span>
<span class="line"><span>String[] strings = {&quot;one&quot;, &quot;two&quot;, &quot;&quot;, &quot;three&quot;, &quot;four&quot;};</span></span>
<span class="line"><span>Arrays.asList(strings)</span></span>
<span class="line"><span>   .stream()</span></span>
<span class="line"><span>   .filter(pred)                  // 过滤掉非空字符串</span></span>
<span class="line"><span>   .forEach(System.out::println); // 只打印空字符串</span></span></code></pre></div><p>在字符串长度为零的情况下，<code>isEmpty</code> Predicate 判定结果为 <code>true</code>。 因此，只有空字符串才能进入管道的 <code>forEach</code> 阶段。</p><p>下一段代码将演示如何将简单的 lambda 或方法引用组合成更丰富的 lambda 或方法引用。考虑这一系列对 <code>IntUnaryOperator</code> 类型的引用的赋值，它接受一个整型参数并返回一个整型值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>IntUnaryOperator doubled = n -&gt; n * 2;</span></span>
<span class="line"><span>IntUnaryOperator tripled = n -&gt; n * 3;</span></span>
<span class="line"><span>IntUnaryOperator squared = n -&gt; n * n;</span></span></code></pre></div><p><code>IntUnaryOperator</code> 是一个 <code>FunctionalInterface</code>，其唯一声明的方法为 <code>applyAsInt</code>。现在可以单独使用或以各种组合形式使用这三个引用 <code>doubled</code>、<code>tripled</code> 和 <code>squared</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>int arg = 5;</span></span>
<span class="line"><span>doubled.applyAsInt(arg); // 10</span></span>
<span class="line"><span>tripled.applyAsInt(arg); // 15</span></span>
<span class="line"><span>squared.applyAsInt(arg); // 25</span></span></code></pre></div><p>以下是一些函数组合的样例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>int arg = 5;</span></span>
<span class="line"><span>doubled.compose(squared).applyAsInt(arg); // 5 求 2 次方后乘 2：50</span></span>
<span class="line"><span>tripled.compose(doubled).applyAsInt(arg); // 5 乘 2 后再乘 3：30</span></span>
<span class="line"><span>doubled.andThen(squared).applyAsInt(arg); // 5 乘 2 后求 2 次方：100</span></span>
<span class="line"><span>squared.andThen(tripled).applyAsInt(arg); // 5 求 2 次方后乘 3：75</span></span></code></pre></div><p>函数组合可以直接使用 lambda 表达式实现，但是引用使代码更简洁。</p><h3 id="构造器引用" tabindex="-1">构造器引用 <a class="header-anchor" href="#构造器引用" aria-label="Permalink to “构造器引用”">​</a></h3><p>构造器引用是另一种函数式编程构造，而这些引用在比 lambda 和方法引用更微妙的上下文中非常有用。再一次重申，代码示例似乎是最好的解释方式。</p>`,76)),t("p",null,[a[1]||(a[1]=s("考虑这个 ",-1)),n(e,{href:"https://en.wikipedia.org/wiki/Plain_old_Java_object"},{default:i(()=>[...a[0]||(a[0]=[s("POJO",-1)])]),_:1}),a[2]||(a[2]=s(" 类：",-1))]),a[19]||(a[19]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>public class BedRocker { // 基岩的居民</span></span>
<span class="line"><span>    private String name;</span></span>
<span class="line"><span>    public BedRocker(String name) { this.name = name; }</span></span>
<span class="line"><span>    public String getName() { return this.name; }</span></span>
<span class="line"><span>    public void dump() { System.out.println(getName()); }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>该类只有一个构造函数，它需要一个 <code>String</code> 参数。给定一个名字数组，目标是生成一个 <code>BedRocker</code> 元素数组，每个名字代表一个元素。下面是使用了函数式结构的代码段：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>String[] names = {&quot;Fred&quot;, &quot;Wilma&quot;, &quot;Peebles&quot;, &quot;Dino&quot;, &quot;Baby Puss&quot;};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Stream&lt;BedRocker&gt; bedrockers = Arrays.asList(names).stream().map(BedRocker::new);</span></span>
<span class="line"><span>BedRocker[] arrayBR = bedrockers.toArray(BedRocker[]::new);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Arrays.asList(arrayBR).stream().forEach(BedRocker::dump);</span></span></code></pre></div><p>在较高的层次上，这个代码段将名字转换为 <code>BedRocker</code> 数组元素。具体来说，代码如下所示。<code>Stream</code> 接口（在包 <code>java.util.stream</code> 中）可以被参数化，而在本例中，生成了一个名为 <code>bedrockers</code> 的 <code>BedRocker</code> 流。</p><p><code>Arrays.asList</code> 实用程序再次用于流化一个数组 <code>names</code>，然后将流的每一项传递给 <code>map</code> 函数，该函数的参数现在是构造器引用 <code>BedRocker::new</code>。这个构造器引用通过在每次调用时生成和初始化一个 <code>BedRocker</code> 实例来充当一个对象工厂。在第二行执行之后，名为 <code>bedrockers</code> 的流由五项 <code>BedRocker</code> 组成。</p><p>这个例子可以通过关注高阶 <code>map</code> 函数来进一步阐明。在通常情况下，一个映射将一个类型的值（例如，一个 <code>int</code>）转换为另一个<em>相同</em>类型的值（例如，一个整数的后继）:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>map(n -&gt; n + 1) // 将 n 映射到其后继</span></span></code></pre></div><p>然而，在 <code>BedRocker</code> 这个例子中，转换更加戏剧化，因为一个类型的值（代表一个名字的 <code>String</code>）被映射到一个<em>不同</em>类型的值，在这个例子中，就是一个 <code>BedRocker</code> 实例，这个字符串就是它的名字。转换是通过一个构造器调用来完成的，它是由构造器引用来实现的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>map(BedRocker::new) // 将 String 映射到 BedRocker</span></span></code></pre></div><p>传递给构造器的值是 <code>names</code> 数组中的其中一项。</p><p>此代码示例的第二行还演示了一个你目前已经非常熟悉的转换：先将数组先转换成 <code>List</code>，然后再转换成 <code>Stream</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Stream&lt;BedRocker&gt; bedrockers = Arrays.asList(names).stream().map(BedRocker::new);</span></span></code></pre></div><p>第三行则是另一种方式 —— 流 <code>bedrockers</code> 通过使用<em>数组</em>构造器引用 <code>BedRocker[]::new</code> 调用 <code>toArray</code> 方法:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>BedRocker[ ] arrayBR = bedrockers.toArray(BedRocker[]::new);</span></span></code></pre></div><p>该构造器引用不会创建单个 <code>BedRocker</code> 实例，而是创建这些实例的整个数组：该构造器引用现在为 <code>BedRocker[]:new</code>，而不是 <code>BedRocker::new</code>。为了进行确认，将 <code>arrayBR</code> 转换为 <code>List</code>，再次对其进行流式处理，以便可以使用 <code>forEach</code> 来打印 <code>BedRocker</code> 的名字。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Fred</span></span>
<span class="line"><span>Wilma</span></span>
<span class="line"><span>Peebles</span></span>
<span class="line"><span>Dino</span></span>
<span class="line"><span>Baby Puss</span></span></code></pre></div><p>该示例对数据结构的微妙转换仅用几行代码即可完成，从而突出了可以将 lambda，方法引用或构造器引用作为参数的各种高阶函数的功能。</p><h3 id="柯里化currying" tabindex="-1"><ruby>柯里化<rt>Currying</rt></ruby> <a class="header-anchor" href="#柯里化currying" aria-label="Permalink to “柯里化Currying”">​</a></h3><p><em>柯里化</em>函数是指减少函数执行任何工作所需的显式参数的数量（通常减少到一个）。（该术语是为了纪念逻辑学家 Haskell Curry。）一般来说，函数的参数越少，调用起来就越容易，也更健壮。（回想一下一些需要半打左右参数的噩梦般的函数！）因此，应将柯里化视为简化函数调用的一种尝试。<code>java.util.function</code> 包中的接口类型适合于柯里化，如以下示例所示。</p><p>引用的 <code>IntBinaryOperator</code> 接口类型是为函数接受两个整型参数，并返回一个整型值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>IntBinaryOperator mult2 = (n1, n2) -&gt; n1 * n2;</span></span>
<span class="line"><span>mult2.applyAsInt(10, 20); // 200</span></span>
<span class="line"><span>mult2.applyAsInt(10, 30); // 300</span></span></code></pre></div><p>引用 <code>mult2</code> 强调了需要两个显式参数，在本例中是 10 和 20。</p><p>前面介绍的 <code>IntUnaryOperator</code> 比 <code>IntBinaryOperator</code> 简单，因为前者只需要一个参数，而后者则需要两个参数。两者均返回整数值。因此，目标是将名为 <code>mult2</code> 的两个参数 <code>IntBinraryOperator</code> 柯里化成一个单一的 <code>IntUnaryOperator</code> 版本 <code>curriedMult2</code>。</p><p>考虑 <code>IntFunction&lt;R&gt;</code> 类型。此类型的函数采用整型参数，并返回类型为 <code>R</code> 的结果，该结果可以是另一个函数 —— 更准确地说，是 <code>IntBinaryOperator</code>。让一个 lambda 返回另一个 lambda 很简单：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>arg1 -&gt; (arg2 -&gt; arg1 * arg2) // 括号可以省略</span></span></code></pre></div><p>完整的 lambda 以 <code>arg1</code> 开头，而该 lambda 的主体以及返回的值是另一个以 <code>arg2</code> 开头的 lambda。返回的 lambda 仅接受一个参数（<code>arg2</code>），但返回了两个数字的乘积（<code>arg1</code> 和 <code>arg2</code>）。下面的概述，再加上代码，应该可以更好地进行说明。</p><p>以下是如何柯里化 <code>mult2</code> 的概述：</p><ul><li>类型为 <code>IntFunction&lt;IntUnaryOperator&gt;</code> 的 lambda 被写入并调用，其整型值为 10。返回的 <code>IntUnaryOperator</code> 缓存了值 10，因此变成了已柯里化版本的 <code>mult2</code>，在本例中为 <code>curriedMult2</code>。</li><li>然后使用单个显式参数（例如，20）调用 <code>curriedMult2</code> 函数，该参数与缓存的参数（在本例中为 10）相乘以生成返回的乘积。。</li></ul><p>这是代码的详细信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// 创建一个接受一个参数 n1 并返回一个单参数 n2 -&gt; n1 * n2 的函数，该函数返回一个（n1 * n2 乘积的）整型数。</span></span>
<span class="line"><span>IntFunction&lt;IntUnaryOperator&gt; curriedMult2Maker = n1 -&gt; (n2 -&gt; n1 * n2);</span></span></code></pre></div><p>调用 <code>curriedMult2Maker</code> 生成所需的 <code>IntUnaryOperator</code> 函数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// 使用 curriedMult2Maker 获取已柯里化版本的 mult2。</span></span>
<span class="line"><span>// 参数 10 是上面的 lambda 的 n1。</span></span>
<span class="line"><span>IntUnaryOperator curriedMult2 = curriedMult2Maker2.apply(10);</span></span></code></pre></div><p>值 <code>10</code> 现在缓存在 <code>curriedMult2</code> 函数中，以便 <code>curriedMult2</code> 调用中的显式整型参数乘以 10：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>curriedMult2.applyAsInt(20); // 200 = 10 * 20</span></span>
<span class="line"><span>curriedMult2.applyAsInt(80); // 800 = 10 * 80</span></span></code></pre></div><p>缓存的值可以随意更改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>curriedMult2 = curriedMult2Maker.apply(50); // 缓存 50</span></span>
<span class="line"><span>curriedMult2.applyAsInt(101);               // 5050 = 101 * 50</span></span></code></pre></div><p>当然，可以通过这种方式创建多个已柯里化版本的 <code>mult2</code>，每个版本都有一个 <code>IntUnaryOperator</code>。</p><p>柯里化充分利用了 lambda 的强大功能：可以很容易地编写 lambda 表达式来返回需要的任何类型的值，包括另一个 lambda。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>Java 仍然是基于类的面向对象的编程语言。但是，借助流 API 及其支持的函数式构造，Java 向函数式语言（例如 Lisp）迈出了决定性的（同时也是受欢迎的）一步。结果是 Java 更适合处理现代编程中常见的海量数据流。在函数式方向上的这一步还使以在前面的代码示例中突出显示的管道的方式编写清晰简洁的 Java 代码更加容易：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dataStream</span></span>
<span class="line"><span>   .parallelStream() // 多线程以提高效率</span></span>
<span class="line"><span>   .filter(...)      // 阶段 1</span></span>
<span class="line"><span>   .map(...)         // 阶段 2</span></span>
<span class="line"><span>   .filter(...)      // 阶段 3</span></span>
<span class="line"><span>   ...</span></span>
<span class="line"><span>   .collect(...);    // 或者，也可以进行归约：阶段 N</span></span></code></pre></div><p>自动多线程，以 <code>parallel</code> 和 <code>parallelStream</code> 调用为例，建立在 Java 的 fork/join 框架上，该框架支持 <ruby>任务窃取<rt>task stealing</rt></ruby> 以提高效率。假设 <code>parallelStream</code> 调用后面的线程池由八个线程组成，并且 <code>dataStream</code> 被八种方式分区。某个线程（例如，T1）可能比另一个线程（例如，T7）工作更快，这意味着应该将 T7 的某些任务移到 T1 的工作队列中。这会在运行时自动发生。</p><p>在这个简单的多线程世界中，程序员的主要职责是编写线程安全函数，这些函数作为参数传递给在流 API 中占主导地位的高阶函数。尤其是 lambda 鼓励编写纯函数（因此是线程安全的）函数。</p><hr>`,44)),t("p",null,[a[4]||(a[4]=s("via: ",-1)),n(e,{href:"https://opensource.com/article/20/1/javastream"},{default:i(()=>[...a[3]||(a[3]=[s("https://opensource.com/article/20/1/javastream",-1)])]),_:1})]),t("p",null,[a[9]||(a[9]=s("作者：",-1)),n(e,{href:"https://opensource.com/users/mkalindepauledu"},{default:i(()=>[...a[5]||(a[5]=[s("Marty Kalin",-1)])]),_:1}),a[10]||(a[10]=s(" 选题：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...a[6]||(a[6]=[s("lujun9972",-1)])]),_:1}),a[11]||(a[11]=s(" 译者：",-1)),n(e,{href:"https://github.com/laingke"},{default:i(()=>[...a[7]||(a[7]=[s("laingke",-1)])]),_:1}),a[12]||(a[12]=s(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:i(()=>[...a[8]||(a[8]=[s("wxy",-1)])]),_:1})]),t("p",null,[a[15]||(a[15]=s("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[13]||(a[13]=[s("LCTT",-1)])]),_:1}),a[16]||(a[16]=s(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:i(()=>[...a[14]||(a[14]=[s("Linux中国",-1)])]),_:1}),a[17]||(a[17]=s(" 荣誉推出",-1))])])}const C=l(r,[["render",g]]);export{v as __pageData,C as default};
